import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = [data[2 + i] for i in range(r)]
total = 0
for r1 in range(r):
    for r2 in range(r1, r):
        for c1 in range(c):
            for c2 in range(c1, c):
                ok = True
                for i in range(r1, r2 + 1):
                    for j in range(c1, c2 + 1):
                        if g[i][j] != '1':
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    total += 1
print(total)

